"use client";

import { useActionState, useState, useTransition } from "react";
import {
  adminAddCustomerNote,
  adminEditCustomerNote,
  adminDeleteCustomerNote,
} from "@/lib/actions";
import { timeAgo } from "@/components/ui/primitives";

export type AdminNote = {
  id: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { name: string; email: string } | null;
};

/**
 * Internal ops notes about a customer. Read-only for non-admin staff; ADMINs
 * can add, edit and delete. All writes go through requireAdmin() actions — the
 * controls are only rendered when `canEdit` so a SUPPORT agent is never shown a
 * button the server will refuse.
 */
export function CustomerNotes({
  userId,
  notes,
  canEdit,
}: {
  userId: string;
  notes: AdminNote[];
  canEdit: boolean;
}) {
  const [addState, addAction, adding] = useActionState(adminAddCustomerNote, {});

  return (
    <div className="card p-0">
      <h2 className="px-5 pt-5 font-semibold">Admin notes</h2>
      <p className="px-5 pt-0.5 text-xs text-slate-500">Internal only — never shown to the customer.</p>

      {canEdit && (
        <form action={addAction} className="space-y-2 px-5 pt-3">
          <input type="hidden" name="userId" value={userId} />
          <textarea
            className="input min-h-20 w-full"
            name="body"
            placeholder="Add a note about this customer…"
            maxLength={5000}
            required
          />
          <div className="flex items-center gap-3">
            <button className="btn-secondary py-1" disabled={adding}>
              {adding ? "Saving…" : "Add note"}
            </button>
            {addState?.error && <span className="text-xs text-red-400">{addState.error}</span>}
          </div>
        </form>
      )}

      {notes.length === 0 ? (
        <p className="px-5 py-8 text-sm text-slate-500">No notes yet.</p>
      ) : (
        <ul className="divide-y divide-white/[0.05] px-5 py-2">
          {notes.map((n) => (
            <NoteRow key={n.id} note={n} canEdit={canEdit} />
          ))}
        </ul>
      )}
    </div>
  );
}

function NoteRow({ note, canEdit }: { note: AdminNote; canEdit: boolean }) {
  const [editing, setEditing] = useState(false);
  const [editState, editAction, saving] = useActionState(adminEditCustomerNote, {});
  const [deleting, startDelete] = useTransition();
  const edited = note.updatedAt.getTime() - note.createdAt.getTime() > 1000;

  return (
    <li className="py-3 text-sm">
      {editing ? (
        <form
          action={async (fd) => {
            await editAction(fd);
            setEditing(false);
          }}
          className="space-y-2"
        >
          <input type="hidden" name="noteId" value={note.id} />
          <textarea className="input min-h-20 w-full" name="body" defaultValue={note.body} maxLength={5000} required />
          <div className="flex items-center gap-3">
            <button className="btn-secondary py-1" disabled={saving}>
              {saving ? "Saving…" : "Save"}
            </button>
            <button type="button" className="btn-ghost py-1 text-xs" onClick={() => setEditing(false)}>
              Cancel
            </button>
            {editState?.error && <span className="text-xs text-red-400">{editState.error}</span>}
          </div>
        </form>
      ) : (
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="whitespace-pre-wrap break-words text-slate-200">{note.body}</p>
            <p className="mt-1 text-xs text-slate-500">
              {note.author?.name ?? "unknown"} · {timeAgo(note.createdAt)}
              {edited ? " · edited" : ""}
            </p>
          </div>
          {canEdit && (
            <div className="flex shrink-0 gap-1">
              <button className="btn-ghost py-1 text-xs" onClick={() => setEditing(true)}>
                Edit
              </button>
              <button
                className="btn-ghost py-1 text-xs text-red-400"
                disabled={deleting}
                onClick={() => {
                  if (window.confirm("Delete this note?")) startDelete(() => adminDeleteCustomerNote(note.id));
                }}
              >
